INSERT INTO `hospital_reports` (`report_id`, `hospital_name`, `report_type`, `report_period`, `source_name`, `raw_json`) VALUES
(1, NULL, 'dataset_11', NULL, 'dataset_11', '{\"hospital_group\": \"{\'name\': \'Le centre hospitalier regional de Laayoune\', \'acronym\': \'CHRL\', \'description\': \'Most important hospital facility in the region.\', \'audit_period\': \'2008-2014\', \'hospitals\': [{\'name\': \'Hopital Moulay El Hassan Ben El Mehdi\', \'service_start_year\': 1986, \'management_mode\': \'SEGMA\', \'personnel_data_2014\': {\'doctors\': 42, \'nurses\': 206, \'administrative_staff\': 88}, \'bed_capacity_2014\': {\'theoretical\': 225, \'functional\': 209}}, {\'name\': \'Hopital Hassan II des specialites\', \'service_start_year\': 1994, \'management_mode\': \'SEGMA\', \'personnel_data_2014\': {\'doctors\': 7, \'nurses\': 56, \'administrative_staff\': 35}, \'bed_capacity_2014\': {\'theoretical\': 144, \'functional\': 80}}], \'audit_findings\': {\'governance_and_management\': {\'strategic_planning_deficiencies\': [\'Lack of activity schedule\', \'Lack of equipment and maintenance plan\', \'Lack of hospital master plan\', \'Lack of monitoring and implementation\'], \'missing_support_and_consultation_committees\': [\'Establishment committee\', \'Nurses council\', \'Monitoring and evaluation committee\', \'Doctors, dentists, and pharmacists council\', \'Nosocomial infection control committee\'], \'patient_mobility_data_discrepancies\': {\'period\': \'July 2015\', \'hospital\': \'Hopital Moulay El Hassan Ben Mehdi\', \'data\': [{\'service\': \'Reanimation\', \'admission_billing_info\': 21, \'care_units_info\': 28}, {\'service\': \'Pediatrie\', \'admission_billing_info\': 69, \'care_units_info\': 62}]}, \'patient_health_data_security_weaknesses\': \'Absence of security measures for access to rooms/offices housing data-containing equipment.\'}, \'care_services_management\': {\'hospital\': \'Hopital Moulay El Hassan Ben El Mehdi\', \'absence_of_triage_system\': \'Externalization of reception and information tasks in emergency service did not ensure triage function due to lack of initiation and training.\', \'non_compliant_recovery_room\': \'Recovery room in operating block used as a biomedical equipment dump, lacking necessary resuscitation equipment and immediate defibrillator access.\', \'absence_of_maternal_death_audits\': \'Maternity service did not conduct clinical audits of maternal deaths as per national plan.\', \'absence_of_isolation_room_in_maternity\': \'Maternity service cannot ensure appropriate isolation for suspected/confirmed infections.\', \'laboratory_missing_biological_exams\': [\'Urine cytobacteriological examination\', \'Puncture fluid bacteriological examination\', \'Stool parasitological examination\', \'Blood culture examination\'], \'absence_of_preventive_maintenance_program_radiology\': \'Radiology service lacks an established and documented preventive maintenance program for all equipment.\', \'drug_and_pharmaceutical_stock_management_failures\': {\'description\': \'Frequent stock ruptures of medications and medical devices.\', \'example_date\': \'2014-01-02\', \'products_out_of_stock\': 81, \'medications_out_of_stock\': 42, \'medical_devices_out_of_stock\': 39}}, \'asset_management\': {\'missing_inventory_numbers_biomedical_equipment\': {\'hospital\': \'Hopital Moulay El Hassan Ben El Mehdi\', \'example_equipment\': [{\'service\': \'Pediatrie\', \'designation\': \'Appareil phototherapie\', \'brand\': \'Ampliflux\', \'model\': \'1CAPOT\', \'serial_number\': \'19226529\'}, {\'service\': \'Pediatrie\', \'designation\': \'COUVEUSE\', \'brand\': \'DRAGER\', \'model\': \'7011\', \'serial_number\': \'16718\'}, {\'service\': \'Pediatrie\', \'designation\': \'COUVEUSE\', \'brand\': \'MEDIPRIMA\', \'model\': \'SATIS3552\', \'serial_number\': \'35528099\'}, {\'service\': \'Pediatrie\', \'designation\': \'POUSSE SERINGUE 2 VOIES\', \'brand\': \'FOURES\', \'model\': \'D-CP\', \'serial_number\': \'07G038/17\'}, {\'service\': \'Pediatrie\', \'designation\': \'POUSSE SERINGUE 2 VOIES\', \'brand\': \'FOURES\', \'model\': \'D-CP\', \'serial_number\': \'07G038/20\'}, {\'service\': \'Pediatrie\', \'designation\': \'POUPINEL\', \'brand\': \'TITANOX\', \'model\': \'A3214535\', \'serial_number\': \'11226\'}, {\'service\': \'Pediatrie\', \'designation\': \'CONCENTRATEUR O2\', \'brand\': \'NUVE\', \'model\': \'NIDEK\', \'serial_number\': \'7210866\'}, {\'service\': \'Pediatrie\', \'designation\': \'CONCENTRATEUR O2\', \'brand\': \'NUVE\', \'model\': \'NIDEK\', \'serial_number\': \'7210874\'}, {\'service\': \'Pediatrie\', \'designation\': \'CONCENTRATEUR O2\', \'brand\': \'AIRSEP\', \'model\': \'ELITE\', \'serial_number\': \'812930\'}, {\'service\': \'Pediatrie\', \'designation\': \'CONCENTRATEUR O2\', \'brand\': \'AIRSEP\', \'model\': \'ELITE\', \'serial_number\': \'987735\'}, {\'service\': \'Pediatrie\', \'designation\': \'CONCENTRATEUR O2\', \'brand\': \'AIRSEP\', \'model\': \'NEWLIFE\', \'serial_number\': \'817077\'}, {\'service\': \'Pediatrie\', \'designation\': \'CONCENTRATEUR O2\', \'brand\': \'AIRSEP\', \'model\': \'NEWLIFE\', \'serial_number\': \'N5114361\'}]}, \'absence_of_computerized_biomedical_management_system\': \'No traceability on repair and maintenance history.\', \'absence_of_medical_engineering_department\': \'No qualified technician or engineer in biomedical engineering within the biomedical equipment management office.\'}, \'financial_resources\': {\'cnops_revenue_collection_issues\': {\'sample_period\': \'First semester 2016\', \'sample_size_invoices\': 107, \'rejection_reasons\': [{\'reason\': \'Lack of verification of insured status (e.g., excluded spouse, non-precounted insured, beneficiary over age limit)\', \'invoices_rejected\': 26, \'percentage_of_rejections\': 0.24}, {\'reason\': \"Incomplete medical records (e.g., missing doctor\'s stamp, non-detailed medical report, missing doctor\'s prescription, missing operative report, blood supply statement)\", \'invoices_rejected\': 50, \'percentage_of_rejections\': 0.47}, {\'reason\': \'Billing errors (e.g., missing stamp/signature on invoice, date rectification, invoice non-compliant with prescription, invoice adjustment, expenses below 200 DH)\', \'invoices_rejected\': 31, \'percentage_of_rejections\': 0.29}]}, \'other_revenue_collection_issues\': {\'low_recovery_rate_non_paying_patients\': {\'period\': \'Second semester 2015\', \'amount_to_recover_dh\': 364460, \'recovery_rate_percent\': 6, \'main_cause\': \'Errors in collecting patient addresses.\'}, \'absence_of_revenue_orders_for_unsatisfied_reminders\': \'Hospital Moulay el Hassan Ben El Mehdi did not issue revenue orders for unsatisfied payment reminders.\'}}, \'catering_hygiene_and_waste_management\': {\'non_compliant_kitchen_hygiene\': [\'Spatial distribution of kitchen does not meet hygiene standards (toilets in meal preparation area).\', \'Presence of cockroaches in the kitchen.\'], \'lack_of_premises_risk_classification\': \'Specifications do not classify premises by infectious risk as per hospital hygiene manual.\', \'absence_of_cleaning_service_control_committee\': \'Administration did not appoint a three-person control committee per hospital as stipulated in CPS article 37.2.\', \'low_medical_personnel_involvement_in_waste_sorting\': {\'description\': \'Low involvement of some health professionals in sorting medical and household waste.\', \'observed_units\': [\'Emergency\', \'Maternity\'], \'issues\': [\'Medical waste placed in green bags (for household waste).\', \'Medical waste mixed with household waste.\', \'Sharps placed directly into yellow inviolable containers without separation.\']}, \'absence_of_medical_waste_treatment_continuity_plan\': {\'shredder_breakdown_period\': \'2009-11 - 2011-11\', \'impact\': \'Medical waste treatment was halted.\', \'single_agent_issue\': \'Only one agent is responsible for waste treatment and masters the shredder, threatening continuity in case of absence.\'}}}, \'minister_of_health_responses\': {\'governance_and_management\': {\'hospital_establishment_project\': {\'status\': \'Priority given to regional care offer schemes (SROS) elaboration, which are a prerequisite for PEH. SROS are in validation phase.\', \'date_of_response\': \'After 2014 audit period\'}, \'consultation_and_support_bodies\': {\'status\': \'Regional health administration frames implementation, but efforts hindered by staff instability (mutations).\', \'date_of_response\': \'After 2014 audit period\'}, \'patient_mobility_information\': {\'status\': \'Since 2015, hospital administration improved coordination between departments and admission office (coordinator appointed).\', \'start_year\': 2015}, \'patient_personal_data_security\': {\'status\': \'Since 2015, access to the digital server room has been limited and secured, located in an isolated area accessible only to the responsible person.\', \'start_year\': 2015}}, \'care_services_management\': {\'medical_triage_system\': {\'status\': \'Lack of medical and nursing staff hinders dedicated triage personnel. Priority given to urgent cases. Since 2015, hostesses assigned for information and orientation in emergencies.\', \'start_year_hostesses\': 2015}, \'operating_room_recovery_room\': {\'status\': \'Rehabilitation and extension project of the regional hospital center is under study, including operating block extension to standards. Project planned for 2018.\', \'planned_year\': 2018}, \'maternal_mortality_clinical_surveys\': {\'status\': \'Clinical surveys on maternal mortality cases are handled by the regional directorate and will be ensured by the head of public health service.\', \'date_of_response\': \'After 2014 audit period\'}, \'maternity_isolation_rooms\': {\'status\': \'Due to low bed capacity. Construction of a new maternity ward meeting criteria programmed in 2018 as part of rehabilitation and extension project.\', \'planned_year\': 2018}, \'laboratory_services\': {\'status\': \'Laboratory received modern equipment in 2018, all reagents and medical devices supplied. Since February 2018, a dedicated space for bacteriological tests. Reconstruction project programmed in 2018.\', \'equipment_year\': 2018, \'bacteriological_space_start_date\': \'2018-02\', \'reconstruction_project_year\': 2018}, \'radiology_preventive_maintenance\': {\'status\': \'Maintenance contracts executed and controlled by provincial delegation, with a regular preventive maintenance program.\', \'date_of_response\': \'After 2014 audit period\'}, \'drug_and_pharmaceutical_stocks\': {\'status\': \'CHR management ensures regular supply, with urgent supply from Supply Division in case of rupture.\', \'date_of_response\': \'After 2014 audit period\'}}, \'asset_management\': {\'medical_equipment_inventory\': {\'status\': \'Since 2015, inventory of all equipment updated and listed with inventory numbers without exception.\', \'start_year\': 2015}}, \'financial_resources\': {\'cnops_revenue_collection\': {\'coordination_with_cnops\': {\'status\': \'Since 2015, coordination with CNOPS, providing CHR access to CNOPS database for insured patient file monitoring.\', \'start_year\': 2015}, \'monitoring_insured_files\': {\'status\': \'Director personally monitors recovery files to prevent rejections.\', \'date_of_response\': \'After 2014 audit period\'}, \'cnops_billing\': {\'status\': \'Since 2015, close coordination with CNOPS. New application adopted in reception and admission service for file review and correction.\', \'start_year\': 2015}}, \'other_revenue_collection\': {\'patient_invoice_recovery_rate\': {\'status\': \'CHR is a reference hospital for three regions, leading to high demand and difficulty in mastering addresses of referred patients. Since 2016, special attention given to invoice recovery.\', \'start_year_focus\': 2016}, \'absence_of_revenue_orders_and_recovery_reminders\': {\'status\': \"Since 2016, CHR administration activated revenue orders for recovery reminders to regularize situation and process previous years\' files.\", \'start_year\': 2016}}}, \'hygiene_and_waste_management\': {\'hospital_kitchen\': {\'status\': \'Since 2015, CHR administration rearranged and rehabilitated kitchen and restaurant buildings according to standards (buildings were 30 years old).\', \'start_year\': 2015}, \'specifications_for_building_classification_by_infection_risk\': {\'status\': \'CHR management noted this observation.\', \'date_of_response\': \'After 2014 audit period\'}, \'cleaning_service_control_committee\': {\'status\': \'Since 2015, a tripartite committee representing most involved services activated to monitor execution of outsourced service contracts.\', \'start_year\': 2015}, \'medical_personnel_involvement_in_medical_waste_sorting\': {\'status\': \'Training and awareness sessions organized for most CHRL personnel to involve them in medical waste sorting.\', \'date_of_response\': \'After 2014 audit period\'}, \'medical_waste_treatment_activity_continuity_plan\': {\'status\': \'CHR ensures treatment and disposal of medical waste from all regional care services (including private facilities) via its shredder.\', \'date_of_response\': \'After 2014 audit period\'}}}}\"}');
INSERT INTO `hospital_reports` (`report_id`, `hospital_name`, `report_type`, `report_period`, `source_name`, `raw_json`) VALUES
(2, 'Centre Hospitalo-Universitaire Mohammed VI Marrakech', 'dataset_12', '2020 - 2021 - 2022', 'dataset_12', '{\"hospital_name\": \"Centre Hospitalo-Universitaire Mohammed VI Marrakech\", \"country\": \"Morocco\", \"ministry\": \"Ministere de la Sante et de la Protection Sociale\", \"report_period\": \"2020 - 2021 - 2022\", \"website\": \"www.chumarrakech.ma\", \"report_details\": \"{\'redaction\': \"Division de l\'Organisation et du Suivi des Affaires Professionnelles\", \'conception_infography\': \'Service de Communication et de Cooperation\', \'director_message_summary\': \'The CHU faced the Covid-19 crisis in 2020-2021 with exemplary investment from professionals, maintaining care, research, and teaching missions, including Covid-19 patient management and vaccination efforts, while also pursuing improvement projects in medical, nursing, social, IT, and logistics fields. This report highlights achievements during 2020-2022.\', \'director_name\': \'Pr Lahcen BOUKHANNI\'}\", \"values\": \"[{\'value_french\': \'Humanisation\', \'value_arabic\': \'انسنة\'}, {\'value_french\': \'Ouverture\', \'value_arabic\': \'انفتاح\'}, {\'value_french\': \'Respect\', \'value_arabic\': \'احترام\'}, {\'value_french\': \'Qualite\', \'value_arabic\': \'جودة\'}, {\'value_french\': \'Ethique\', \'value_arabic\': \'اخلاقيات\'}, {\'value_french\': \'Excellence\', \'value_arabic\': \'تفوق\'}, {\'value_french\': \'Integrite\', \'value_arabic\': \'نزاهة\'}]\", \"general_overview\": \"{\'legal_status\': \"Etablissement public dote de la personnalite morale et de l\'autonomie financiere\", \'supervision\': \'Ministere de la Sante\', \'creation_law\': \'Loi 82.00 promulguee par le Dahir 1.01.206 du 10 Joumada II 1422 (30 aout 2001)\', \'missions\': [{\'name\': \'Soins\', \'description\': \'Prodigue des soins de niveau tertiaire, offrant des prestations medicales et chirurgicales courantes et specialisees en urgence ou en activites programmees.\'}, {\'name\': \'Recherche\', \'description\': \"Travaux de recherche medicale et des soins infirmiers menes en collaboration avec la Faculte de Medecine et de Pharmacie et des unites de formation et de recherche etrangeres. Contribue aux objectifs de politique de sante de l\'Etat.\"}, {\'name\': \'Enseignement\', \'description\': \"En partenariat avec la Faculte de Medecine et de Pharmacie et Instituts Superieurs des professions infirmieres et techniques de sante (ISPITS). Concourt a l\'enseignement clinique universitaire, postuniversitaire medicale et pharmaceutique et participe a la formation pratique du personnel infirmier.\"}, {\'name\': \'Sante publique\', \'description\': \'Contribue a la realisation des objectifs fixes en matiere de politique de sante pronee par le ministere de la sante.\'}]}\", \"organization\": \"{\'administration_structure\': \"Administre par un conseil d\'administration assiste d\'un comite de gestion et gere par un directeur.\", \'governance_roles\': [{\'role\': \"Conseil d\'administration\", \'description\': \"Organe deliberant, investi de tous les pouvoirs de decisions necessaires a l\'administration de l\'etablissement.\"}, {\'role\': \'Comite de gestion\', \'description\': \"Charge de veiller, dans l\'intervalle des reunions du conseil d\'administration a l\'execution des decisions de ce dernier.\"}, {\'role\': \'Directeur\', \'description\': \"Charge d\'executer les decisions du conseil d\'administration et du comite de gestion.\"}], \'key_personnel\': [{\'title\': \'Directeur General\', \'name\': \'Pr Lahcen BOUKHANNI\'}, {\'title\': \'Secretaire General\', \'name\': \'Mr Ali ARKOUBI\'}], \'divisions_and_services\': [{\'division\': \'Division des affaires financieres\', \'head\': \'Mme Fatiha EL HAYOUNI\', \'services\': [\'Service Budget (Mr Abdelaaziz HOUSNI)\', \'Service Comptabilite (Mr Abderrahman BADDOU)\', \'Service Recouvrement et Recettes (Mr Abderrahim SIMOU)\']}, {\'division\': \"Division d\'investissement et approvisionnement\", \'head\': \'Mr Abdelaziz ZITOUNI\', \'services\': [\'Service de la Pharmacie (Mme Khadija KHATIM)\', \'Service des Travaux et Prestations de Service (Mme Houda ARKOUBI)\', \'Service Equipements et Fournitures (Mr Abdelaziz HOUSNI)\']}, {\'division\': \'Division des ressources humaines et de developpement professionnel continu\', \'head\': \'Mr Abderrahmane EI MOUSSAOUI\', \'services\': [\'Service Gestion du personnel (Mr Abdelaziz AADADOUCH)\', \'Service du Developpement Professionnel Continu (Mr Noureddine ERRASSAA)\', \'Service Gestion de la Paie (Mme Mahassine KHALALI)\', \'Service des Affaires Juridiques et Sociales\']}, {\'division\': \"Division du patrimoine hospitalier et de l\'ingenierie\", \'head\': \'Mr Said AIT OUFQIR\', \'services\': [\'Service des Installations Techniques (Mr Abderrahim EL OUAHВІ)\', \'Servicedu Batiment Patrimoine et Parc Automobile (Mr Oussama EL MESSOUSSI)\', \'Service Equipements et Maintenance biomedicale (Mr Rachid LAAZOUZI)\', \'Service Hygiene Hospitaliere (Mme Khadija TOKANE)\']}, {\'division\': \"Division des systemes d\'information hospitaliers\", \'head\': \'Mr Mhamed OUMAHIYA\', \'services\': [\"Service Gestion de l\'Infrastructure et des Systemes (Mme Hind DAKI)\", \'Service Exploitation et Architecture SI (Mme Houda AIT BRAHIM)\', \'Service de Management des Projets SI (Mr Abdelmoula BOUCHAM)\', \"Service de Production de l\'Information (Mme Hasna SOUMMANE)\"]}, {\'division\': \"Division de l\'organisation de l\'enseignement hospitalier, de la recherche scientifique et de l\'innovation\", \'head\': \'Mr abdelmjid TAKOUI\', \'services\': [\"Service de l\'Enseignement Hospitalier (Mr Anas TARWATE)\", \"Service de la Recherche Scientifique et de l\'innovation (Mme Hayat LAFRIKH)\"]}, {\'division\': \"Division de l\'organisation et du suivi des affaires professionnelles\", \'head\': \'Mr EL HALOUANI Abdelaziz\', \'services\': [\'Service Affaires Medicales et Epidemiologie (Mme Hafida BOUHAJA)\', \'Service des Affaires Paramedicales et Techniques de Sante (Mr Morad BELKOURI)\', \'Service Qualite et gestion des risques\']}, {\'service_directly_under_general_secretary\': \'Service Audit Interne\', \'head\': \'Mme Khadija OUGUERRI\'}, {\'service_directly_under_general_secretary\': \'Service Communication et Cooperation\', \'head\': \'Mme Jihan QODAD\'}, {\'service_directly_under_general_secretary\': \'Service Controle de Gestion\', \'head\': \'Mr EL IDRISSI My lahcen\'}]}\", \"abbreviations\": \"[{\'acronym\': \'A/O\', \'meaning\': \"Appel d\'Offre\"}, {\'acronym\': \'AMO\', \'meaning\': \'Assurance maladie obligatoire\'}, {\'acronym\': \'AT\', \'meaning\': \'Accident de travail\'}, {\'acronym\': \'AVP\', \'meaning\': \'Accident de la voie publique\'}, {\'acronym\': \'CCV\', \'meaning\': \'Chirurgie cardiovasculaire\'}, {\'acronym\': \'CHU\', \'meaning\': \'Centre Hospitalo-Universitaire\'}, {\'acronym\': \'CL\', \'meaning\': \'Capacite en lits\'}, {\'acronym\': \'CNOPS\', \'meaning\': \'Caisse Nationale des Organismes de Prevoyance Sociale\'}, {\'acronym\': \'CPS\', \'meaning\': \'Cahier de Prescription Speciale\'}, {\'acronym\': \'CRC\', \'meaning\': \'Centre de recherche clinique\'}, {\'acronym\': \'DMS\', \'meaning\': \'Duree moyenne de sejour\'}, {\'acronym\': \'HDJ\', \'meaning\': \'Hopital du jour\'}, {\'acronym\': \'HIN\', \'meaning\': \'Hopital Ibn Nafis\'}, {\'acronym\': \'HIT\', \'meaning\': \'Hopital Ibn Tofail\'}, {\'acronym\': \'HOH\', \'meaning\': \"Hopital d\'Oncologie et d\'Hematologie\"}, {\'acronym\': \'HME\', \'meaning\': \'Hopital Mere – Enfant\'}, {\'acronym\': \'IFCS\', \'meaning\': \'Intervalle de rotation\'}, {\'acronym\': \'IRM\', \'meaning\': \'Imagerie par resonance magnetique\'}, {\'acronym\': \'JH\', \'meaning\': \"Journee d\'hospitalisation\"}, {\'acronym\': \'RMS\', \'meaning\': \'Region Marrakech-Safi\'}, {\'acronym\': \'ORL\', \'meaning\': \'Oto Rhino Laryngologie\'}, {\'acronym\': \'Prog\', \'meaning\': \'Programme (es)\'}, {\'acronym\': \'PNI\', \'meaning\': \'Places Non Identifiee\'}, {\'acrony