(3, 'Centre Hospitalo-Universitaire Mohammed VI Oujda', 'dataset_13', NULL, 'dataset_13', '{\"project_name\": \"Projet d\'Etablissement Hospitalier\", \"project_period\": \"2023-2025\", \"hospital_name\": \"Centre Hospitalo-Universitaire Mohammed VI Oujda\", \"inauguration_date\": \"2014-07\", \"previous_peh_context\": \"{\'first_version_elaboration_period\': \'2014-2019\', \'first_version_implementation_period\': \'2019-2022\', \'second_version_aim\': \'consolidation des acquis, comblement des ecarts et contribution aux grands chantiers de reformes prones par Sa Majeste\'}\", \"royal_discourses_references\": \"[{\'date\': \'2018\', \'event\': \'Discours du Trone\', \'theme\': \"Appel a une prompte refonte du dispositif de protection sociale, marque par un eparpillement des interventions et un faible taux de couverture et d\'efficacite.\"}, {\'date\': \'2020-07-30\', \'event\': \'Discours Royal/Fete du Trone\', \'theme\': \"Renouvellement de l\'appel a la refonte du dispositif de protection sociale. Remerciements aux acteurs du secteur sanitaire et forces de securite pour leur devouement dans la lutte contre la pandemie de COVID-19.\"}, {\'date\': \'2021-07-30\', \'event\': \'Discours Royal/Fete du Trone\', \'theme\': \"Souverainete sanitaire comme composante essentielle de la securite strategique du pays, lancement d\'un projet de fabrication de vaccins, medicaments et materiel medical. Souhait que le \'Pacte national pour le developpement\' soit le cadre de reference pour les priorites du pays.\"}, {\'date\': \'2021-10-08\', \'event\': \'Discours Royal/nouvelle legislature\', \'theme\': \'Definir les priorites et les projets a mettre en chantier au cours de son mandat et mobiliser les ressources necessaires pour assurer leur financement.\'}]\", \"reference_framework\": \"[\'Orientations Royales\', \'Constitution (Art 31, 20, 34, 154, 13, 27, 32,71) & conventions internationales\', \'Loi-cadre 21-09, loi 72-18, relatives a la protection sociale et registres\', \'Loi 27-22, modifiant et completant la loi 65-00 (Basculement RAMED-AMO)\', \"P. Loi-cadre N°06-22, relatif au systeme national de sante, abrogeant la loi-cadre 34-09 (offre de soins et ses textes d\'application)\", \'Loi de finance\', \"Loi-cadre 97-13 relative a la protection et a la promotion des personnes en situation d\'handicap\", \"Schemas Regionaux de l\'Offre de Soins (SROS1&2) & Projets d\'Etablissement Hospitaliers des hopitaux de la Region de l\'Oriental PEHs\", \'Nouveau modele de developpement propose & l\\\'Objectif de Developpement Durable 3, relatif a \"Bonne Sante et Bien-etre\", ODD3\', \'La circulaire N°85 du 25 decembre 2019 /elaboration et mise en œuvre du Projet Medical Regional\', \'PLAN « SANTE 2025 »\', \'Lettre de Cadrage de Monsieur le Chef du Gouvernement du 03 Aout 2022\', \'Conventions de cooperation et de partenariat\', \"Rapports d\'audit internes et externes\"]\", \"royal_orientations\": \"[{\'date\': \'2018-07-30\', \'event\': \'Fete du Trone\', \'theme\': \"Critique de l\'eparpillement des programmes de soutien et de protection sociale, faible ciblage des categories eligibles, appel a une refonte profonde du systeme national de sante.\"}, {\'date\': \'2020-07-30\', \'event\': \'Fete du Trone\', \'theme\': \"Rappel de l\'appel de 2018 pour une refonte du dispositif de protection sociale, soulignant son eparpillement et faible efficacite.\"}, {\'date\': \'2021-07-30\', \'event\': \'Fete du Trone\', \'theme\': \"Souverainete sanitaire comme composante essentielle de la securite strategique, souhait que le \'Pacte national pour le developpement\' soit le cadre de reference pour les priorites du pays.\"}, {\'date\': \'2021-10-08\', \'event\': \'Vendredi, nouvelle legislature\', \'theme\': \'Definir les priorites et les projets a mettre en chantier au cours de son mandat et mobiliser les ressources necessaires pour assurer leur financement.\'}, {\'date\': \'2022-07-30\', \'event\': \'Fete du Trone\', \'theme\': \"Mise en œuvre du projet de generalisation de la protection sociale et mise a niveau du systeme de sante. Lancement de projets pour la souverainete sanitaire. Plus de six millions d\'adherents a l\'AMO pour travailleurs non-salaries et leurs familles. Achevement de la couverture sanitaire obligatoire pour les beneficiaires du RAMED d\'ici fin d\'annee.\"}]\", \"situation_analysis\": \"{\'key_figures_2014_2022\': [{\'dimension\': \'CAPACITE LITIERE\', \'indicator\': \'Capacite litiere theorique\', \'2014\': 673, \'2015\': 673, \'2016\': 673, \'2017\': 673, \'2018\': 673, \'2019\': 673, \'2020\': 673, \'2021\': 673, \'2022\': 673, \'total\': 673, \'average\': None}, {\'dimension\': \'CAPACITE LITIERE\', \'indicator\': \'Capacite litiere fonctionnelle\', \'2014\': 453, \'2015\': 483, \'2016\': 508, \'2017\': 542, \'2018\': 542, \'2019\': 557, \'2020\': 557, \'2021\': 590, \'2022\': 593, \'total\': None, \'average\': None}, {\'dimension\': \'Activite Hospitaliere\', \'indicator\': \'Admissions en (HC)\', \'2014\': 2962, \'2015\': 11365, \'2016\': 15075, \'2017\': 16699, \'2018\': 17182, \'2019\': 18531, \'2020\': 16538, \'2021\': 19221, \'2022\': 20384, \'total\': 137957, \'average\': 15329}, {\'dimension\': \'Activite Hospitaliere\', \'indicator\': \'Admissions en (HDJ)\', \'2014\': 5627, \'2015\': 11633, \'2016\': 14385, \'2017\': 18451, \'2018\': 19707, \'2019\': 20503, \'2020\': 19786, \'2021\': 23261, \'2022\': 22030, \'total\': 155383, \'average\': 17265}, {\'dimension\': \'Activite Hospitaliere\', \'indicator\': \'Total des hospitalisations (HC+HDJ)\', \'2014\': 8589, \'2015\': 22998, \'2016\': 29460, \'2017\': 35150, \'2018\': 36889, \'2019\': 39034, \'2020\': 36324, \'2021\': 42482, \'2022\': 42414, \'total\': 293340, \'average\': 32593}, {\'dimension\': \'Activite Hospitaliere\', \'indicator\': \"Journees d\'hospitalisations\", \'2014\': 27737, \'2015\': 89755, \'2016\': 124459, \'2017\': 140513, \'2018\': 150864, \'2019\': 151020, \'2020\': 124109, \'2021\': 153244, \'2022\': 139858, \